-- Les champs parlent par concept : le dictionnaire qui relie les 2 133 champs.
--
-- POURQUOI. Les 77 grilles de `20261105110000` nomment 1539 codes de champ différents
-- pour des notions souvent identiques : `raison_sociale_emetteur`, `nom_client`,
-- `employeur_raison_sociale` et `tireur_nom` sont tous une raison sociale ;
-- `matricule_fiscal_emetteur`, `client_mf` et `payeur_matricule` sont tous un
-- matricule fiscal. Sans ce lien, un expert ne vaut que pour UN champ, et le
-- moteur qui naît de la base devrait en générer deux mille. Avec lui, l'expert
-- du matricule fiscal lit les 51 champs qui en portent un.
--
-- CE QUE FAIT CETTE MIGRATION.
--   1. Les familles d'experts (`ref.experts`, 9) et, pour chacune, les types de
--      champ qu'elle sait lire (`ref.expert_types`). Un concept est lu par UNE famille ;
--      un champ dont le type n'est pas lisible par la famille de son concept est refusé.
--   2. Les rôles (`ref.roles`, 34) : à qui appartient la notion sur la pièce.
--      Libellés des familles et des rôles en fr, en, ar (`ref.labels`, R12).
--   3. `ref.concepts` : la notion (code, libellé), sa famille, et si elle porte sur une
--      partie (`porte_sur_une_partie`). Rattachée au pack tunisien en cours, datée en
--      littéral (R11), livrée en défaut (`defaut_a_valider`, R10).
--   4. `ref.grille_champs` gagne `concept_id` (obligatoire) et `role` (clé étrangère vers
--      `ref.roles`). Un champ garde son code et ses repères : rien n'est renommé.
--   5. La garde, PERMANENTE : des déclencheurs différés refusent tout champ hors du
--      dictionnaire, et `ref.champs_hors_dictionnaire()` le dit au test d'intégrité
--      (`apps/api/src/la-base-tient-son-integrite.test.ts`), qui vérifie aussi qu'aucun
--      concept n'est sans champ.
--   6. Le semis : 1181 concepts ; 222 sont partagés par plusieurs champs et
--      couvrent 1174 champs ; les autres sont propres à un seul champ (une ligne du
--      bilan n'a pas de jumelle). Par famille :
--      date 67, identifiant 42, libelle 433, montant 424, nombre 69, presence 59, reference 35, taux 27, tiers 25.
--      30 concepts portent sur une partie ; 443 champs ont un rôle, 1690 n'en ont pas.
--      Ce que le dictionnaire a révélé des grilles : 17 types de champ corrigés.
--   7. Les repères arabes : un ajouté, des repères trop faibles retirés.
--   8. `concept_id` devient obligatoire.
--
-- LES RÔLES, une règle par cas — un rôle nul a UN sens : le champ ne porte sur aucune
-- partie (un total, une date de la pièce, un lieu). Un concept qui porte sur une partie
-- (raison sociale, matricule fiscal, adresse, RIB, signature...) exige un rôle ; les
-- autres le refusent.
--   - Une pièce nomme chaque partie par UN rôle : le bailleur d'une quittance est son
--     `creancier`, puisque la quittance l'appelle ainsi.
--   - Le vendeur est `fournisseur` et l'acheteur `client`, quel que soit le nom que leur
--     donne la pièce (émetteur d'une facture, vendeur, opérateur, commerçant, abonné,
--     acquéreur) : le même fournisseur se reconnaît ainsi d'un bon de commande à sa
--     facture, alors que l'émetteur, lui, change de camp.
--   - `emetteur` et `destinataire` : l'expéditeur et le destinataire d'un envoi ou d'un
--     message (bon de livraison, enveloppe TEIF), qui peuvent différer du vendeur et de
--     l'acheteur. « Expéditeur » en est un synonyme et n'est pas un rôle.
--   - En douane, la case de l'expéditeur est celle de l'`exportateur`, celle du
--     destinataire celle de l'`importateur` ; le `declarant` est celui qui dépose la
--     déclaration (un transitaire, le cas échéant).
--   - `contribuable` : la personne dont l'impôt est en cause, qu'elle déclare, paie, soit
--     vérifiée ou taxée (« redevable » de la vignette compris). `administration` : le
--     bureau qui délivre, vise ou encaisse. `entreprise` : la société dont la pièce est
--     l'acte ou l'état (statuts, procès-verbal, états financiers, extrait RNE).
--   - `dirigeant` comprend le gérant ; `debiteur` l'emprunteur ; `contrepartie` le tiers
--     d'un compte ou d'une opération quand la pièce ne dit pas s'il est client ou
--     fournisseur ; `partie` chacune des parties d'un contrat nommées ensemble.
--
-- COMMENT LE LIEN EST FAIT. Par règles déterministes, sans modèle, puis revu concept par
-- concept : le jeton de rôle est retiré du code, le reste est cherché dans une table de
-- synonymes. Les concepts à un seul champ des familles date, identifiant, référence et
-- tiers ont tous été relus, et rattachés à un concept partagé quand ils en doublaient un.
-- C'est un DÉFAUT : l'expertise peut le corriger sans migration (R10).
--
-- Corrigée en place le 1er novembre 2026 (audit indépendant du dictionnaire) : elle n'a
-- jamais été jouée sur une base partagée, et une migration qui défait la précédente
-- deux lignes plus loin aurait laissé deux vérités à lire.

-- ============================================================ 1. LES FAMILLES D'EXPERTS

create table if not exists ref.experts (
  code text primary key check (code ~ '^[a-z][a-z_]*$')
);

comment on table ref.experts is
  'Les lecteurs génériques du sudoku : chaque concept est lu et vérifié par l''un d''eux.';

-- Les types de champ que chaque famille sait lire. La liste des types est celle de
-- `ref.grille_champs.type` (20261105110000).
create table if not exists ref.expert_types (
  expert text not null references ref.experts(code),
  type   text not null check (type in ('texte', 'montant', 'identifiant', 'liste', 'date',
                                         'booleen', 'nombre', 'adresse', 'periode', 'taux')),
  primary key (expert, type)
);

comment on table ref.expert_types is
  'Compatibilité type ↔ famille : un champ n''est rattaché qu''à un concept dont la famille '
  'sait lire son type (garde permanente, section 5).';

