  ('presence', 'booleen');

-- ====================================================================== 2. LES RÔLES

create table if not exists ref.roles (
  code text primary key check (code ~ '^[a-z][a-z_]*$')
);

comment on table ref.roles is
  'À qui appartient une notion sur la pièce. Les règles de choix sont dans l''en-tête de '
  '20261115100000_les_champs_parlent_par_concept.sql.';

