-- ============================================================ 3. LE DICTIONNAIRE

create table if not exists ref.concepts (
  id                   uuid primary key default gen_random_uuid(),
  pack_version_id      uuid not null references ref.jurisdiction_packs(id) on delete cascade,
  code                 text not null check (code ~ '^[a-z][a-z0-9_]*$'),
  libelle              text not null,
  -- La famille d'experts qui lit et vérifie ce concept.
  expert               text not null references ref.experts(code),
  -- Vrai : la notion appartient à une partie, et chacun de ses champs dit laquelle.
  porte_sur_une_partie boolean not null,
  statut               text not null check (statut in ('defaut_a_valider', 'arrete')),
  valid_from           date not null,
  valid_to             date check (valid_to is null or valid_to >= valid_from),
  unique (pack_version_id, code, valid_from)
);

comment on table ref.concepts is
  'Le dictionnaire des concepts : une notion partagée par les champs de plusieurs grilles, '
  'et la famille d''experts qui la lit. Défaut livré par Malica (R10).';

alter table ref.concepts enable row level security;
alter table ref.concepts force row level security;
revoke all on table ref.concepts from public, anon, service_role;
grant select on table ref.concepts to authenticated;
drop policy if exists ref_concepts_sel on ref.concepts;
create policy ref_concepts_sel on ref.concepts for select to authenticated using (true);

create index if not exists concepts_pack_idx on ref.concepts (pack_version_id, code);
create index if not exists concepts_expert_idx on ref.concepts (expert);

-- ============================================= 4. LE CHAMP DIT SON CONCEPT ET SON RÔLE

-- `concept_id` devient obligatoire à la fin du semis (section 8).
alter table ref.grille_champs
  add column if not exists concept_id uuid references ref.concepts(id),
  add column if not exists role text references ref.roles(code);

create index if not exists grille_champs_concept_id_fk_idx on ref.grille_champs (concept_id);
create index if not exists grille_champs_role_idx on ref.grille_champs (role);

comment on column ref.grille_champs.concept_id is
  'La notion que porte ce champ (dictionnaire `ref.concepts`) : deux champs du même concept '
  'sont lus par le même expert.';
comment on column ref.grille_champs.role is
  'À qui appartient la notion sur la pièce (`ref.roles`). Nul si et seulement si le concept '
  'ne porte sur aucune partie (un total, une date de la pièce, un lieu).';

create or replace view public.ref_concepts_v with (security_invoker = true) as
  select id, pack_version_id, code, libelle, expert, statut, valid_from, valid_to,
         porte_sur_une_partie
    from ref.concepts;

-- Ajoutées À LA FIN : `create or replace view` refuse tout autre changement.
create or replace view public.ref_grille_champs_v with (security_invoker = true) as
  select id, grille_id, parcelle, code, libelle, type, obligatoire, condition, reperes_fr,
         reperes_ar, format_code, groupe, fondement, source_fondement, statut, concept_id, role
    from ref.grille_champs;

revoke all on table public.ref_concepts_v from public, anon, service_role;
grant select on table public.ref_concepts_v to authenticated;
revoke all on table public.ref_grille_champs_v from public, anon, service_role;
grant select on table public.ref_grille_champs_v to authenticated;

-- ======================================================================= 5. LA GARDE
--
-- Posée AVANT le semis : les déclencheurs sont différés, ils relisent chaque champ semé
-- au commit de cette migration, puis chaque écriture qui suivra. Une seule source des
-- écarts, que le test d'intégrité relit aussi.

create or replace function ref.champs_hors_dictionnaire(
  p_champ uuid default null, p_concept uuid default null, p_expert text default null)
returns table (champ text, ecart text)
language sql stable
set search_path = ''
as $$
  select g.code || '/' || c.code, e.ecart
    from ref.grille_champs c
    join ref.grilles g on g.id = c.grille_id
    left join ref.concepts k on k.id = c.concept_id
   cross join lateral (values
         (case when k.id is null then 'sans concept' end),
         (case when k.pack_version_id <> g.pack_version_id
               then 'concept ' || k.code || ' d''un autre pack que sa grille' end),
         (case when k.id is not null
                and not exists (select 1 from ref.expert_types t
                                 where t.expert = k.expert and t.type = c.type)
               then 'type ' || c.type || ' illisible par la famille ' || k.expert end),
         (case when k.porte_sur_une_partie and c.role is null
               then 'rôle exigé : ' || k.code || ' porte sur une partie' end),
         (case when not k.porte_sur_une_partie and c.role is not null
               then 'rôle ' || c.role || ' refusé : ' || k.code || ' ne porte sur aucune partie' end)
       ) as e(ecart)
   where e.ecart is not null
     and (p_champ is null or c.id = p_champ)
     and (p_concept is null or c.concept_id = p_concept)
     and (p_expert is null or k.expert = p_expert)
$$;

comment on function ref.champs_hors_dictionnaire(uuid, uuid, text) is
  'Les champs qui contredisent le dictionnaire : sans concept, concept d''un autre pack, '
  'type illisible par la famille, rôle exigé ou refusé. Vide, toujours.';

create or replace function ref.garder_le_dictionnaire()
returns trigger
language plpgsql
set search_path = ''
as $$
declare
  v_ecarts text;
begin
  if tg_table_name = 'grille_champs' then
    select string_agg(champ || ' : ' || ecart, ' ; ') into v_ecarts
      from ref.champs_hors_dictionnaire(p_champ => new.id);
  elsif tg_table_name = 'concepts' then
    select string_agg(champ || ' : ' || ecart, ' ; ') into v_ecarts
      from ref.champs_hors_dictionnaire(p_concept => new.id);
  else
    select string_agg(champ || ' : ' || ecart, ' ; ') into v_ecarts
      from ref.champs_hors_dictionnaire(p_expert => old.expert);
  end if;
  if v_ecarts is not null then
    -- Une faute du référentiel livré, pas un refus adressé à un utilisateur.
    raise exception 'dictionnaire des concepts : %', v_ecarts using errcode = '23000';
  end if;
  return null;
end;
$$;

drop trigger if exists grille_champs_tient_le_dictionnaire on ref.grille_champs;
create constraint trigger grille_champs_tient_le_dictionnaire
  after insert or update of concept_id, role, type, grille_id on ref.grille_champs
  deferrable initially deferred
  for each row execute function ref.garder_le_dictionnaire();

drop trigger if exists concepts_tient_le_dictionnaire on ref.concepts;
create constraint trigger concepts_tient_le_dictionnaire
  after update of expert, porte_sur_une_partie, pack_version_id on ref.concepts
  deferrable initially deferred
  for each row execute function ref.garder_le_dictionnaire();

drop trigger if exists expert_types_tient_le_dictionnaire on ref.expert_types;
create constraint trigger expert_types_tient_le_dictionnaire
  after update or delete on ref.expert_types
  deferrable initially deferred
  for each row execute function ref.garder_le_dictionnaire();

-- ===================================================================== 6. LE SEMIS

