  ) as v(code, libelle, expert, porte_sur_une_partie)
 where p.jurisdiction = 'TN' and p.effective_from <= date '2026-01-01'
   and (p.effective_to is null or p.effective_to >= date '2026-01-01')
   and exists (select 1 from ref.grilles g where g.pack_version_id = p.id)
on conflict (pack_version_id, code, valid_from) do nothing;

-- Ce que le dictionnaire a révélé des types de la grille : une signature est lue oui ou
-- non (`booleen`), même écrite en texte ; une année de déclaration CNSS est une période ;
-- la durée d'un CDD aussi ; le renouvellement d'un CDD est une clause ; le QR code d'une
-- facture se constate, il ne se décode pas.
update ref.grille_champs c
   set type = v.type
  from (values
    ('bail_commercial', 'signatures', 'booleen'),
    ('bilan', 'signataire', 'booleen'),
    ('carte_identification_fiscale', 'cachet_signature', 'booleen'),
    ('certificat_retenue_source', 'signature_cachet', 'booleen'),
    ('contrat_assurance', 'signatures', 'booleen'),
    ('contrat_cdd', 'duree', 'periode'),
    ('contrat_cdd', 'renouvellement', 'texte'),
    ('contrat_commercial', 'signatures', 'booleen'),
    ('declaration_cnss_trimestrielle', 'annee', 'periode'),
    ('declaration_douane_import', 'signature_declarant', 'booleen'),
    ('declaration_mensuelle', 'signature_cachet', 'booleen'),
    ('facture', 'qr_code', 'booleen'),
    ('facture_electronique', 'qr_code_visible', 'booleen'),
    ('pv_inventaire_stocks', 'signatures', 'booleen'),
    ('quittance_paiement', 'visa_cachet', 'booleen'),
    ('recepisse_quittance_cnss', 'annee', 'periode'),
    ('statuts', 'signatures', 'booleen')
  ) as v(grille, champ, type)
  join ref.grilles g on g.code = v.grille
 where c.grille_id = g.id and c.code = v.champ;

