 where c.grille_id = g.id and c.code = v.champ;

-- ============================================== 7. LES REPÈRES ARABES

-- Banc de 30 factures arabes fictives, 1er novembre 2026 : le numéro s'imprime
-- « فاتورة عدد » (l'usage tunisien de « facture n° »), absent des repères. Sans
-- lui, l'expert du numéro refusait 21 pièces sur 30 ; avec lui, 3 (des erreurs
-- de l'OCR, refusées et non devinées).

update ref.grille_champs c
   set reperes_ar = c.reperes_ar || array['فاتورة عدد']
  from ref.grilles g
 where g.id = c.grille_id and g.code = 'facture' and c.code = 'numero_facture'
   and not ('فاتورة عدد' = any (c.reperes_ar));

-- Des repères qui désignent autre chose que le champ, retirés (un repère faux coûte
-- plus qu'un repère absent : il ancre la lecture sur le mauvais jeton) :
--   - le nom complet de la CNSS sur le numéro d'affiliation de l'employeur : il est
--     imprimé en en-tête de la pièce, loin du numéro ;
--   - « العنوان » seul, quand la pièce porte deux adresses ou plus qui l'ont tous : il
--     ne dit pas à quelle partie l'adresse appartient ;
--   - « عقد كراء » sur le type de bail : c'est le titre de tout bail ;
--   - « مجلس الإدارة » sur le mode de direction et sur la date de la réunion du conseil :
--     c'est le nom d'un organe, imprimé partout dans la pièce ;
--   - « السنة المحاسبية » sur la date d'ouverture de l'exercice : il nomme l'exercice, pas
--     son ouverture (il reste juste sur l'exercice de la déclaration annuelle).

update ref.grille_champs c
   set reperes_ar = array_remove(c.reperes_ar, 'الصندوق الوطني للضمان الاجتماعي')
  from ref.concepts k
 where k.id = c.concept_id and k.code = 'numero_cnss' and c.role = 'employeur';

update ref.grille_champs c
   set reperes_ar = array_remove(c.reperes_ar, 'العنوان')
 where 'العنوان' = any (c.reperes_ar)
   and (select count(*) from ref.grille_champs x
         where x.grille_id = c.grille_id and 'العنوان' = any (x.reperes_ar)) > 1;

update ref.grille_champs c
   set reperes_ar = array_remove(c.reperes_ar, v.repere)
  from (values
    ('bail_commercial', 'type_bail', 'عقد كراء'),
    ('statuts', 'mode_direction', 'مجلس الإدارة'),
    ('pv_conseil_administration', 'date_reunion', 'مجلس الإدارة'),
    ('statuts', 'exercice_debut', 'السنة المحاسبية')
  ) as v(grille, champ, repere)
  join ref.grilles g on g.code = v.grille
 where c.grille_id = g.id and c.code = v.champ;

-- ============================================== 8. TOUT CHAMP A SON CONCEPT

-- La garde relit maintenant chaque champ semé (une table qui attend des vérifications
-- différées ne se modifie pas), puis la colonne devient obligatoire.
set constraints all immediate;

alter table ref.grille_champs alter column concept_id set not null;
